import{d as g,C as a,o as h,c as d,j as n,a as e,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const z=JSON.parse('{"title":"中庸·第25章","description":"《中庸》第 25 章——诚者自成也，而道自道也：诚者物之终始，不诚无物；成己仁也，成物知也，合内外之道。","frontmatter":{"title":"中庸·第25章","description":"《中庸》第 25 章——诚者自成也，而道自道也：诚者物之终始，不诚无物；成己仁也，成物知也，合内外之道。","category":"guide","aliases":["第25章","中庸第25章","诚者自成"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-25.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-25.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-25.md"},w=g({...m,setup(c){const t=[{id:"zicheng",label:"诚者自成也 · 而道自道也",showLabel:!0,sentences:[["诚者",{text:"自成",glossary:"zicheng"},"也，而道",{text:"自道",glossary:"zidao"},"也。"]],note:"「诚者自成也，而道自道也」——诚是自己成就自己（自成），道由自己踩出（自道）。二者皆不假外求，是「为己之学」的根。"},{id:"wuzhongshi",label:"诚者物之终始 · 不诚无物",showLabel:!0,sentences:[["诚者",{text:"物之终始",glossary:"wuzhongshi"},"，",{text:"不诚无物",glossary:"buchengwuwu"},"。是故君子",{text:"诚之为贵",glossary:"chengweigui"},"。"]],note:"「诚者物之终始，不诚无物」——诚贯穿一事之终始；不诚，则事不成（无物）。所以「君子诚之为贵」——君子以诚为最贵。"},{id:"chengji",label:"成己仁也 · 成物知也 · 合内外之道",showLabel:!0,sentences:[["诚者非",{text:"自成己",glossary:"chengji"},"而已也，所以",{text:"成物",glossary:"chengwu"},"也。成己，仁也；成物，知也。",{text:"性之德",glossary:"xingzhide"},"也，",{text:"合内外之道",glossary:"heneiwai"},"也，故",{text:"时措之宜",glossary:"shicuozhiyi"},"也。"]],note:"「诚者非自成己而已也，所以成物也」——诚不只是成就自己，也要成就外物。故「成己，仁也；成物，知也」（知＝智）；这两者是「性之德也，合内外之道也」，所以能「时措之宜也」——随时施行而皆得其宜。"}],r=[{id:"zicheng",term:"自成",pinyin:"zì chéng",meaning:"朱注：「诚者物之所以自成。」诚是万物之所以能够成就自身者。"},{id:"zidao",term:"自道",pinyin:"zì dǎo",meaning:"道：读 dǎo。朱注：「道者人之所当自行也。」道是人自己所当行的路。"},{id:"wuzhongshi",term:"物之终始",pinyin:"wù zhī zhōng shǐ",meaning:"朱注：「天下之物，皆实理之所为，故必得是理，然后有是物。」"},{id:"buchengwuwu",term:"不诚无物",pinyin:"bù chéng wú wù",meaning:"朱注：「人之心一有不实，则虽有所为亦如无有。」心不实，所做等于没做。"},{id:"chengweigui",term:"诚之为贵",pinyin:"chéng zhī wéi guì",meaning:"以诚为贵。"},{id:"chengji",term:"成己",pinyin:"chéng jǐ",meaning:"成就自己——此为仁（体之存）。"},{id:"chengwu",term:"成物",pinyin:"chéng wù",meaning:"成就外物——此为知（用之发）。诚不止于自了。"},{id:"xingzhide",term:"性之德",pinyin:"xìng zhī dé",meaning:"朱注：「是皆吾性之固有，而无内外之殊。」仁与知都是本性所固有。"},{id:"heneiwai",term:"合内外之道",pinyin:"hé nèi wài zhī dào",meaning:"合内外为一之道。内（成己）与外（成物）不是两件事。"},{id:"shicuozhiyi",term:"时措之宜",pinyin:"shí cuò zhī yí",meaning:"措：施行。随时施行而皆得其宜。"}];return(p,i)=>{const s=a("DaoTextReading"),l=a("DaoKeywordCards");return h(),d("div",null,[i[0]||(i[0]=n("h1",{id:"中庸·第25章",tabindex:"-1"},[e("中庸·第25章 "),n("a",{class:"header-anchor",href:"#中庸·第25章","aria-label":'Permalink to "中庸·第25章"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=n("p",null,[e("第二十五章讲「诚」的两句定义——"),n("strong",null,"诚者自成，道自道"),e("；接着是全篇分量极重的一句："),n("strong",null,"不诚无物"),e("；最后落在「成己（仁）／成物（知）」与「合内外之道」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),o(s,{colophon:"诚者自成 · 不诚无物 · 成己成物",tone:"ink",sections:t,glossary:r,"default-mode":"slips","aria-label":"中庸·第25章 原文"}),i[3]||(i[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(l,{items:[{term:"自成",pinyin:["zì","chéng"],meaning:"物之所以自成——属物。"},{term:"自道",pinyin:["zì","dǎo"],meaning:"道：读 dǎo。人所当自行——属人。"},{term:"不诚无物",pinyin:["bù","chéng","wú","wù"],meaning:"朱注：「人之心一有不实，则虽有所为亦如无有。」"},{term:"成己",pinyin:["chéng","jǐ"],meaning:"成就自己，为仁。"},{term:"成物",pinyin:["chéng","wù"],meaning:"成就外物，为知——诚不止于自了。"},{term:"合内外之道",pinyin:["hé","nèi","wài","zhī","dào"],meaning:"内（成己）与外（成物）本是一事，非两途。"}]}),i[4]||(i[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>诚者自成也 · 而道自道也</strong>：诚，是物之所以自成；道，是人自己所当行的路。</p><p><strong>诚者物之终始 · 不诚无物</strong>：诚是万物的终始，不诚就没有物。所以君子以诚为贵。</p><p><strong>成己仁也 · 成物知也</strong>：诚不只是成就自己而已，还要成就外物。成就自己是仁，成就外物是智。这是本性所固有，是合内外为一之道，所以随时施行都很适宜。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十五章围绕「诚」说了三件事：</p><ol><li><strong>诚者自成，道自道</strong>——万物靠诚而成，人靠自己行道</li><li><strong>诚者物之终始，不诚无物</strong>——诚是物的始终；不诚，等于没有</li><li><strong>成己（仁）／成物（知）</strong>——诚不止于成就自己；这是「性之德」「合内外之道」，故「时措之宜」</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「不诚无物」是全篇最重的一句</strong>：朱注把它讲得很硬——「人之心一有不实，则虽有所为亦如<strong>无有</strong>」。不是「做得不好」，而是「等于没做」。</li><li><strong>它把「诚」从德行变成存在条件</strong>：前面几章讲诚的作用（尽性、致曲、前知），本章说诚是<strong>物之所以为物</strong>。这样「诚」就不只是一种品质，而是根本。</li><li><strong>「成己／成物」承第 22、23 章</strong>：尽己之性 → 尽人尽物；致曲 → 形著明动变化；本章直说成己与成物<strong>是一件事</strong>（合内外），并分别配以仁与智。</li><li><strong>「时措之宜」是活的</strong>：诚不是死守，而是「随时施行皆得其宜」——这与第 2 章「时中」相接。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「不诚无物」自查</strong>：今天做的哪一件事，若把「实」抽掉，其实等于没做？</li><li><strong>成己与成物一起看</strong>：只修自己的（自了汉），或只管外面的（事务主义），都是切开了「合内外」。</li><li><strong>「时措之宜」</strong>：同一份真诚，对不同人、不同场合，表达方式要变。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>诚是万物得以成就自己的东西；道是人自己所当走的路。</p><p>接着是最重的一句：<strong>诚是万物的始终，不诚就等于没有物。</strong> 所以君子以诚为贵。</p><p>而诚不只成就自己，还要成就外物：<strong>成就自己是仁，成就外物是智</strong>。这两者都是人性本有的，是「合内外」的一条道——所以随时施用都很恰当。</p><p>这一章把「诚」从一种品德，说成了<strong>事物存在的前提</strong>：不实，就没有。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「不诚无物」——今天做的哪一件事，抽掉「实」之后，等于没做？</li><li>「成己，仁也；成物，知也」——我是不是把这两件事切开了？</li><li>「时措之宜」——同一份真诚，我有没有对不同的人只会用同一种表达？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-24">中庸·第24章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-26">中庸·第26章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{z as __pageData,w as default};
